begin;select no_plan();
select is((select public from storage.buckets where id='house-guide-images'),false,'Guide bucket private');
select is((select public from storage.buckets where id='site-video-uploads'),false,'Unverified video bucket private');
select is((select public from storage.buckets where id='site-videos'),false,'Verified video bucket remains private');
select set_config('request.jwt.claims','{"sub":"a3b45db1-7c15-4528-a4ba-be625665fb6d"}',true);set local role authenticated;
select ok(public.save_hero_media('bf88f504-051f-4fdc-ab73-4fa12d715817','photo',''),'Owner can choose photo');
select throws_ok($$select public.save_hero_media('ff24bacc-47d2-40bc-9210-f860e98892fd','photo','')$$,'42501',null,'Cross org config rejected');
select throws_ok($$select public.save_hero_media('bf88f504-051f-4fdc-ab73-4fa12d715817','video','bf88f504-051f-4fdc-ab73-4fa12d715817/hero/11111111-1111-4111-8111-111111111111.mp4')$$,'22023',null,'Cannot publish missing video');
select lives_ok($$insert into storage.objects(bucket_id,name) values ('site-videos','bf88f504-051f-4fdc-ab73-4fa12d715817/hero/11111111-1111-4111-8111-111111111111.mp4')$$,'Owner uploads own media');
select throws_like($$insert into storage.objects(bucket_id,name) values ('site-videos','ff24bacc-47d2-40bc-9210-f860e98892fd/hero/11111111-1111-4111-8111-111111111111.mp4')$$,'%row-level security%','Cannot upload to other org');
select throws_ok($$select public.save_hero_media('bf88f504-051f-4fdc-ab73-4fa12d715817','video','bf88f504-051f-4fdc-ab73-4fa12d715817/hero/11111111-1111-4111-8111-111111111111.mp4')$$,'22023',null,'Unverified direct upload cannot be published');
select throws_like($$select public.register_verified_hero_video('bf88f504-051f-4fdc-ab73-4fa12d715817','a3b45db1-7c15-4528-a4ba-be625665fb6d','bf88f504-051f-4fdc-ab73-4fa12d715817/hero/11111111-1111-4111-8111-111111111111.mp4')$$,'%permission denied%','Owner cannot attest their own video');
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select ok(public.register_verified_hero_video('bf88f504-051f-4fdc-ab73-4fa12d715817','a3b45db1-7c15-4528-a4ba-be625665fb6d','bf88f504-051f-4fdc-ab73-4fa12d715817/hero/11111111-1111-4111-8111-111111111111.mp4'),'Only server registers verification');
select set_config('request.jwt.claims','{"sub":"a3b45db1-7c15-4528-a4ba-be625665fb6d"}',true);set local role authenticated;
select ok(public.save_hero_media('bf88f504-051f-4fdc-ab73-4fa12d715817','video','bf88f504-051f-4fdc-ab73-4fa12d715817/hero/11111111-1111-4111-8111-111111111111.mp4'),'Owner publishes video with existing poster');
select ok(public.save_hero_media('bf88f504-051f-4fdc-ab73-4fa12d715817','photo',''),'Owner returns to photo');
reset role;set local role anon;
select is((select mode from public.property_hero_media where org_id='bf88f504-051f-4fdc-ab73-4fa12d715817'),'photo','Visitor reads public media choice');
select throws_like($$select public.save_hero_media('bf88f504-051f-4fdc-ab73-4fa12d715817','photo','')$$,'%permission denied%','Anon cannot change hero');
select * from finish();rollback;
